const newId=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint32Array(4)),x=>x.toString(16)).join('-');
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={role:'company',users:[{id:'u1',name:'خالد أحمد',role:'supervisor'},{id:'u2',name:'أحمد علي',role:'employee'},{id:'u3',name:'سعيد فهد',role:'employee'}],ops:[{id:'RO-1001',name:'جرد نهاية الشهر',branch:'الفيصلية · جدة',type:'reference',supervisor:'u1',staff:['u2','u3'],status:'open',date:'2026-10-31',ref:[{barcode:'628100100101',name:'تيشيرت قطني أسود',qty:45},{barcode:'628100100102',name:'بنطال كتان',qty:28},{barcode:'628100100103',name:'جاكيت شتوي',qty:15},{barcode:'628100100104',name:'فستان كتان إيطالي',qty:30}]},{id:'RO-1002',name:'جرد قسم الملابس الشتوية',branch:'المحاميد · جدة',type:'open',supervisor:'u1',staff:['u2'],status:'open',date:'2026-10-31',ref:[]}],logs:[{id:'l1',op:'RO-1001',barcode:'628100100101',qty:43,user:'u2',location:'A1',note:'',time:'2026-10-31T08:10:00Z',excluded:false},{id:'l2',op:'RO-1001',barcode:'628100100102',qty:30,user:'u3',location:'A2',note:'',time:'2026-10-31T08:18:00Z',excluded:false},{id:'l3',op:'RO-1001',barcode:'628100100103',qty:15,user:'u2',location:'A3',note:'',time:'2026-10-31T08:24:00Z',excluded:false},{id:'l4',op:'RO-1001',barcode:'628100100101',qty:2,user:'u3',location:'A1',note:'يحتاج مراجعة التكرار',time:'2026-10-31T08:30:00Z',excluded:false}],resolutions:{},audit:[],plan:1};
let db;try{db=JSON.parse(localStorage.getItem('ro-demo-v1'))||structuredClone(seed)}catch{db=structuredClone(seed)}let page='landing',selected='RO-1001',filter='',statusFilter='all';
const labels={dashboard:'نظرة عامة',operations:'عمليات الجرد',scan:'تسجيل الجرد',review:'المراجعة والتكرارات',team:'فريق العمل',reports:'التقارير',plans:'الباقات والاشتراك',settings:'الإعدادات',landing:'عن RO'};
const roles={company:'حساب الشركة',supervisor:'المسؤول',employee:'موظف الجرد'};function save(action){if(action)db.audit.unshift({text:action,time:new Date().toISOString()});localStorage.setItem('ro-demo-v1',JSON.stringify(db))}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}function go(p){page=p;filter='';statusFilter='all';render();window.scrollTo(0,0)}
function user(id){return db.users.find(u=>u.id===id)?.name||'—'}function op(id){return db.ops.find(o=>o.id===id)}function activeUser(){return db.role==='employee'?'u2':'u1'}function visibleOps(){return db.ops.filter(o=>db.role==='company'||(db.role==='supervisor'?o.supervisor===activeUser():o.staff.includes(activeUser())))}function canManage(){return db.role==='company'}function canReview(){return db.role!=='employee'}function logs(id){return db.logs.filter(l=>(!id||l.op===id)&&!l.excluded)}function groups(){const g={};for(const l of logs()){if(!visibleOps().some(o=>o.id===l.op))continue;let key=[l.op,l.barcode,l.location].join('|');(g[key]??=[]).push(l)}return Object.entries(g).filter(([,v])=>v.length>1)}function badges(s){return `<span class="badge ${s==='closed'?'gray':''}">${s==='closed'?'مغلقة':'قيد التنفيذ'}</span>`}function progress(o){if(o.type==='open')return '<span class="muted">جرد مفتوح</span>';let n=new Set(logs(o.id).filter(l=>o.ref.some(r=>r.barcode===l.barcode)).map(l=>l.barcode)).size,p=o.ref.length?Math.round(n/o.ref.length*100):0;return `<div class="progress"><div class="meter"><em style="width:${p}%"></em></div>${p}%</div>`}
function head(title,desc,actions=''){return `<div class="heading"><div><div class="eyebrow">RO / WORKSPACE</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}function newButton(){return canManage()?'<button class="primary" onclick="newOperation()">＋ إنشاء عملية جرد</button>':''}function stats(){let os=visibleOps(),ls=logs().filter(l=>os.some(o=>o.id===l.op));return `<div class="stats">${[['عمليات قيد التنفيذ',os.filter(o=>o.status==='open').length,'عملية متاحة للفريق','▤'],['سجلات الجرد',ls.length,'إدخالات محفوظة في هذه التجربة','▥'],['الوحدات المعدودة',ls.reduce((a,b)=>a+b.qty,0),'وحدة تم تسجيلها','⌗'],['تكرارات للمراجعة',groups().filter(([k])=>!db.resolutions[k]).length,'تنبيهات بانتظار القرار','◷']].map(([t,n,d,i])=>`<div class="stat"><div class="stat-top">${t}<i>${i}</i></div><strong>${n.toLocaleString('en')}</strong><small>${d}</small></div>`).join('')}</div>`}
function operationsTable(limit){let os=visibleOps().filter(o=>(o.name+' '+o.branch+' '+o.id).includes(filter)&&(statusFilter==='all'||o.status===statusFilter));if(limit)os=os.slice(0,limit);return `<div class="table-wrap"><table><thead><tr><th>عملية الجرد</th><th>النوع</th><th>الحالة</th><th>التقدم</th><th>الفريق</th><th></th></tr></thead><tbody>${os.map(o=>`<tr><td><b>${esc(o.name)}</b><small>${esc(o.id)} · ${esc(o.branch)}</small></td><td>${o.type==='open'?'مفتوح':'بمرجع'}</td><td>${badges(o.status)}</td><td>${progress(o)}</td><td>${o.staff.length} موظفين<small>${esc(user(o.supervisor))}</small></td><td><button class="dots" onclick="detail('${o.id}')">عرض ←</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">لا توجد عمليات مطابقة</td></tr>'}</tbody></table></div>`}
function teamWidget(){return `<div class="panel"><div class="panel-title"><h2>إنجاز فريق الجرد</h2><button class="link" onclick="go('team')">عرض الفريق</button></div>${db.users.filter(u=>u.role==='employee').map(u=>`<div class="team-row"><i>${esc(u.name[0])}</i><div>${esc(u.name)}<small>عدد إدخالات الجرد</small></div><strong>${logs().filter(l=>l.user===u.id).length}</strong></div>`).join('')}</div>`}
function dashboard(){return head('كل أرقامك، أمامك.','تابع عمليات الجرد، وخلّ فريقك يركز على الدقة.',`<button onclick="go('reports')">↧ تصدير التقارير</button>${newButton()}`)+`<section class="hero"><div><small>COUNT SMART. SEE CLEAR.</small><h2>من أول باركود، إلى آخر فرق.</h2><p>أنشئ عملية، وزّع فريقك، وتابع النتائج من مكان واحد.<br>جرد أوضح. قرارات أسهل.</p></div><div class="hero-art" aria-hidden="true"><div class="barcode"><b>Ⅱ▏ⅢⅡ▏ⅠⅡ</b><small>RO INVENTORY</small></div><div class="hero-tag">✓ كل وحدة محسوبة</div></div></section>`+stats()+`<div class="grid"><div><section class="panel"><div class="panel-title"><h2>عمليات الجرد الأخيرة <small> / ${visibleOps().length} عمليات</small></h2><button class="link" onclick="go('operations')">كل العمليات ←</button></div>${operationsTable(4)}</section>${teamWidget()}</div><div class="secondary-grid"><section class="panel"><div class="panel-title"><h2>آخر النشاطات</h2><span class="badge gray">محلي</span></div><div class="activity">${(db.audit.length?db.audit:[{text:'تم تجهيز مساحة العمل التجريبية',time:new Date().toISOString()},{text:'تنبيه: تكرار باركود في الموقع A1',time:new Date().toISOString()},{text:'جرد نهاية الشهر جاهز للمتابعة',time:new Date().toISOString()}]).slice(0,4).map(a=>`<div class="activity-item"><i>✓</i><div><p>${esc(a.text)}</p><small>${new Date(a.time).toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join('')}</div></section><div class="note"><b>الدقة تبدأ من طريقة العد.</b>قسّم الرفوف بين الموظفين لتقليل تكرار عدّ الصنف في الموقع نفسه.<br><button class="link" onclick="go('review')">مراجعة التنبيهات ←</button></div></div></div>`}
function operations(){return head('عمليات الجرد','كل عملية بفريقها، وأصنافها، ونتائجها.',newButton())+`<section class="panel"><div class="toolbar"><input aria-label="البحث عن عملية" placeholder="ابحث باسم العملية أو الفرع…" oninput="filter=this.value;refreshTable()"><select aria-label="حالة العملية" onchange="statusFilter=this.value;refreshTable()"><option value="all">كل الحالات</option><option value="open">قيد التنفيذ</option><option value="closed">مغلقة</option></select></div><div id="opTable">${operationsTable()}</div></section>`}function refreshTable(){$('#opTable').innerHTML=operationsTable()}
function modal(html,fn){$('#dialogForm').innerHTML=html;$('#dialogForm').onsubmit=async e=>{e.preventDefault();try{await fn(new FormData(e.target))}catch(err){toast(err.message)}};$('#dialog').showModal()}function closeDialog(){$('#dialog').close()}function modalButtons(t){return `<div class="modal-actions"><button class="primary" type="submit">${t}</button><button type="button" onclick="closeDialog()">إلغاء</button></div>`}
function csvParse(text){const rows=[];let row=[],v='',q=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){row.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v);if(row.some(x=>x.trim()))rows.push(row);row=[];v=''}else v+=c}if(q)throw Error('علامات اقتباس غير مغلقة في الملف');row.push(v);if(row.some(x=>x.trim()))rows.push(row);return rows}
function reference(text){const rows=csvParse(text.replace(/^\uFEFF/,'')),h=rows.shift()?.map(x=>x.trim().toLowerCase());if(!h||!['barcode','name','qty'].every(x=>h.includes(x)))throw Error('الملف يحتاج الأعمدة barcode,name,qty');let seen=new Set;return rows.map((r,i)=>{let barcode=r[h.indexOf('barcode')]?.trim(),name=r[h.indexOf('name')]?.trim(),qty=Number(r[h.indexOf('qty')]);if(!barcode||!name||!Number.isSafeInteger(qty)||qty<0||seen.has(barcode))throw Error(`بيانات غير صحيحة أو باركود مكرر في السطر ${i+2}`);seen.add(barcode);return {barcode,name,qty}})}
function newOperation(){if(!canManage()||!requireOperationCredit())return;modal(`<h2>عملية جرد جديدة</h2><p>اختر طريقة الجرد، ثم حدد المسؤول والفريق.</p><label class="field">اسم العملية<input name="name" required maxlength="100" placeholder="مثال: جرد نهاية الشهر"></label><div class="two"><label class="field">الفرع / المستودع<input name="branch" required maxlength="80"></label><label class="field">نوع الجرد<select name="type" onchange="$('#refField').hidden=this.value!=='reference'"><option value="open">جرد مفتوح</option><option value="reference">جرد بمرجع أصناف</option></select></label></div><div id="refField" hidden><label class="field">ملف CSV للأصناف<input type="file" name="file" accept=".csv,text/csv"></label><small>الأعمدة المطلوبة: barcode,name,qty — الباركود يُحفظ كنص.</small><button type="button" class="link" onclick="downloadTemplate()">تحميل قالب الاستيراد</button></div><label class="field">المسؤول<select name="supervisor" required>${db.users.filter(u=>u.role==='supervisor').map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><div class="field">موظفو الجرد<div class="checks">${db.users.filter(u=>u.role==='employee').map(u=>`<label><input type="checkbox" name="staff" value="${u.id}"> ${esc(u.name)}</label>`).join('')}</div></div>${modalButtons('إنشاء وفتح العملية')}`,async f=>{if(!f.getAll('staff').length)throw Error('اختر موظف جرد واحدًا على الأقل');let ref=[];if(f.get('type')==='reference'){const file=f.get('file');if(!file?.size)throw Error('ارفع ملف الأصناف المرجعي');if(file.size>2000000)throw Error('الحد التجريبي للملف 2 ميجابايت');ref=reference(await file.text());if(!ref.length)throw Error('الملف لا يحتوي أصنافًا')}let name=f.get('name').trim();if(!name)throw Error('أدخل اسم العملية');assertOperationCredit();let id='RO-'+Date.now().toString().slice(-8);db.ops.unshift({id,name,branch:f.get('branch').trim(),type:f.get('type'),supervisor:f.get('supervisor'),staff:f.getAll('staff'),status:'open',date:new Date().toISOString().slice(0,10),ref});save('إنشاء عملية '+name);closeDialog();go('operations');toast('تم إنشاء العملية محليًا')})}
function detail(id){selected=id;let o=op(id);if(!visibleOps().includes(o))return;page='detail';render();}function detailPage(){let o=op(selected);if(!o)return operations();return head(esc(o.name),`${esc(o.id)} · ${esc(o.branch)} · المسؤول: ${esc(user(o.supervisor))}`,`<button onclick="go('operations')">كل العمليات</button>${o.status==='open'?'<button class="primary" onclick="go(\'scan\')">تسجيل جرد</button>':''}${canManage()?`<button onclick="toggleStatus()">${o.status==='open'?'إغلاق العملية':'إعادة فتح العملية'}</button>`:''}`)+`<section class="panel"><div class="panel-title"><h2>ملخص العملية</h2>${badges(o.status)}</div><div class="toolbar">${progress(o)}<span class="muted">${logs(o.id).length} إدخالات · ${o.ref.length} أصناف مرجعية</span></div>${resultsTable(o.id)}</section>`}function toggleStatus(){if(!canManage())return;let o=op(selected);if(o.status==='open'&&groups().some(([k])=>k.startsWith(o.id+'|')&&!db.resolutions[k]))return toast('عالج التكرارات المعلقة قبل إغلاق العملية');o.status=o.status==='open'?'closed':'open';save('تغيير حالة '+o.name);render()}
function scanPage(){let os=visibleOps().filter(o=>o.status==='open');if(!os.length)return head('تسجيل الجرد','العمليات المفتوحة المسندة لك')+'<div class="panel empty">لا توجد عملية مفتوحة مسندة لك حاليًا.</div>';if(!os.some(o=>o.id===selected))selected=os[0].id;return head('كل مسحة، خطوة للأمام.','استخدم قارئ باركود خارجي أو أدخل الباركود يدويًا.')+`<div class="warning">وضع تجريبي: الحفظ على هذا المتصفح فقط. لا توجد مزامنة سحابية أو حماية فعلية للأجهزة حتى تفعيل الخادم.</div><section class="panel scan"><form id="scanForm"><label class="field">عملية الجرد<select name="operation" onchange="selected=this.value">${os.map(o=>`<option value="${o.id}" ${o.id===selected?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>${db.role==='employee'?'':`<label class="field">تسجيل باسم الموظف<select name="employee">${db.users.filter(u=>u.role==='employee'&&op(selected).staff.includes(u.id)).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label>`}<label class="field">الباركود<input name="barcode" required maxlength="100" autocomplete="off" placeholder="امسح أو اكتب الباركود" autofocus></label><div class="two"><label class="field">الكمية<input name="qty" type="number" min="0" max="1000000000" step="1" value="1" required></label><label class="field">الرف / الموقع<input name="location" required value="A1" maxlength="80"></label></div><label class="field">ملاحظات<textarea name="note" rows="2" maxlength="500" placeholder="ملاحظة على الصنف أو حالة العبوة"></textarea></label><button class="primary">＋ حفظ سجل الجرد</button></form></section><section class="panel"><div class="panel-title"><h2>آخر إدخالاتك</h2><small>محفوظة على هذا الجهاز</small></div>${logsTable(db.role==='employee'?activeUser():null)}</section>`}
function attachScan(){let form=$('#scanForm');if(!form)return;form.elements.operation.onchange=e=>{selected=e.target.value;render()};form.onsubmit=e=>{e.preventDefault();let f=new FormData(form),o=op(f.get('operation')),barcode=f.get('barcode').trim(),qty=Number(f.get('qty')),uid=db.role==='employee'?activeUser():f.get('employee');if(!o||o.status!=='open'||!o.staff.includes(uid)||!barcode||!Number.isSafeInteger(qty)||qty<0||qty>1e9)return toast('تحقق من العملية والموظف والكمية');db.logs.push({id:newId(),op:o.id,barcode,qty,user:uid,location:f.get('location').trim(),note:f.get('note').trim(),time:new Date().toISOString(),excluded:false});let key=[o.id,barcode,f.get('location').trim()].join('|');delete db.resolutions[key];save('تسجيل جرد بواسطة '+user(uid));render();toast('تم حفظ الإدخال محليًا');$('#scanForm').elements.barcode.focus()}}
function logsTable(uid){let ls=logs().filter(l=>visibleOps().some(o=>o.id===l.op)&&(!uid||l.user===uid)).slice().reverse().slice(0,30);return `<div class="table-wrap"><table><thead><tr><th>الباركود</th><th>الكمية</th><th>الموظف</th><th>الموقع</th><th>ملاحظة</th></tr></thead><tbody>${ls.map(l=>`<tr><td dir="ltr">${esc(l.barcode)}</td><td>${l.qty}</td><td>${esc(user(l.user))}</td><td>${esc(l.location)}</td><td>${esc(l.note)||'—'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد إدخالات بعد</td></tr>'}</tbody></table></div>`}
function reviewPage(){return head('التكرار واضح. والقرار موثّق.','راجع الأصناف التي عُدّت أكثر من مرة في الموقع نفسه.')+`<section class="panel">${groups().map(([key,ls],i)=>`<div class="review-card"><div><span class="badge ${db.resolutions[key]?'':'amber'}">${db.resolutions[key]?'تمت المعالجة':'بانتظار المراجعة'}</span><h3>${esc(op(ls[0].op)?.name)} · ${esc(ls[0].barcode)}</h3><p>الموقع ${esc(ls[0].location)} · ${ls.map(l=>`${esc(user(l.user))}: ${l.qty}`).join(' / ')}</p>${db.resolutions[key]?`<p>القرار: اعتماد مجموع الإدخالات · بواسطة ${esc(db.resolutions[key].actor)}</p>`:''}</div>${!db.resolutions[key]?`<button onclick="resolveDuplicate(${i})">اعتماد الجمع</button><button onclick="excludeDuplicate(${i})">استبعاد آخر إدخال</button>`:''}</div>`).join('')||'<div class="empty">لا توجد تكرارات للمراجعة ✓</div>'}</section>`}function resolveDuplicate(i){if(!canReview())return;let [k]=groups()[i];db.resolutions[k]={actor:db.role==='company'?'حساب الشركة':user('u1'),time:new Date().toISOString()};save('معالجة تكرار واعتماد الجمع');render();toast('تم توثيق القرار')}function excludeDuplicate(i){if(!canReview())return;let [k,ls]=groups()[i];let l=ls.at(-1);l.excluded=true;save('استبعاد إدخال مكرر '+l.barcode+' في '+l.location);render();toast('تم الاستبعاد مع حفظ القرار في سجل النشاط')}
function results(id){let o=op(id),ls=logs(id),codes=new Set([...o.ref.map(r=>r.barcode),...ls.map(l=>l.barcode)]);return [...codes].map(barcode=>{let ref=o.ref.find(r=>r.barcode===barcode),count=ls.filter(l=>l.barcode===barcode).reduce((a,l)=>a+l.qty,0),expected=ref?.qty??null;return {barcode,name:ref?.name||'صنف بدون مرجع',expected,count,diff:expected===null?null:count-expected}})}function resultsTable(id){return `<div class="table-wrap"><table><thead><tr><th>الباركود</th><th>الصنف</th><th>المرجع</th><th>المعدود</th><th>الفرق</th></tr></thead><tbody>${results(id).map(r=>`<tr><td dir="ltr">${esc(r.barcode)}</td><td>${esc(r.name)}</td><td>${r.expected??'—'}</td><td>${r.count}</td><td><span class="badge ${r.diff?'amber':'gray'}">${r.diff===null?'بلا مرجع':r.diff>0?'+'+r.diff:r.diff}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">لم يبدأ العد بعد</td></tr>'}</tbody></table></div>`}
function reports(){let os=visibleOps();if(!os.some(o=>o.id===selected))selected=os[0]?.id;return head('نتائج جاهزة للمراجعة.','قارن المعدود بالمرجع، وصدّر النتائج مع الباركود كاملًا.',`<button onclick="exportReport('csv')">CSV</button><button onclick="exportReport('json')">JSON</button><button onclick="window.print()">طباعة / حفظ PDF</button>`)+`<div class="warning">Excel وWord والتقارير بشعار الشركة تُضاف في مرحلة الربط. التصدير المتاح الآن: CSV وJSON والطباعة إلى PDF.</div><section class="panel"><div class="toolbar"><select aria-label="اختر عملية التقرير" onchange="selected=this.value;render()">${os.map(o=>`<option value="${o.id}" ${o.id===selected?'selected':''}>${esc(o.name)}</option>`).join('')}</select></div>${selected?resultsTable(selected):'<div class="empty">أنشئ عملية أولًا</div>'}</section>`}
function download(text,name,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function safeCell(s){s=String(s??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}function exportReport(type){if(!op(selected))return toast('اختر عملية');let rows=results(selected);if(type==='json')download(JSON.stringify({operation:op(selected).name,results:rows},null,2),selected+'.json','application/json');else download('\ufeff'+[['barcode','name','expected','count','difference'],...rows.map(r=>[r.barcode,r.name,r.expected??'',r.count,r.diff??''])].map(r=>r.map(safeCell).join(',')).join('\r\n'),selected+'.csv','text/csv;charset=utf-8')}function downloadTemplate(){download('\ufeffbarcode,name,qty\r\n628100100101,تيشيرت قطني,45\r\n','ro-reference-template.csv','text/csv;charset=utf-8')}
function team(){return head('فريقك، وصلاحيات واضحة.','حساب الشركة يختار المسؤول والموظفين لكل عملية.',canManage()?'<button class="primary" onclick="newUser()">＋ إضافة مستخدم تجريبي</button>':'')+`<div class="warning">إضافة المستخدمين هنا للتجربة فقط؛ لا تنشئ حسابات دخول فعلية ولا ترسل دعوات.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الدور</th><th>العمليات المسندة</th><th>إدخالات الجرد</th><th>الوحدات</th></tr></thead><tbody>${db.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${roles[u.role]}</td><td>${db.ops.filter(o=>o.staff.includes(u.id)||o.supervisor===u.id).length}</td><td>${logs().filter(l=>l.user===u.id).length}</td><td>${logs().filter(l=>l.user===u.id).reduce((a,l)=>a+l.qty,0)}</td></tr>`).join('')}</tbody></table></div></section>`}function newUser(){if(!canManage()||!requireUserSlot())return;modal(`<h2>إضافة عضو للفريق</h2><label class="field">الاسم<input name="name" required maxlength="80"></label><label class="field">الدور<select name="role"><option value="employee">موظف الجرد</option><option value="supervisor">المسؤول</option></select></label>${modalButtons('إضافة')}`,f=>{let name=f.get('name').trim();if(!name)throw Error('أدخل اسم المستخدم');assertUserSlot();db.users.push({id:newId(),name,role:f.get('role')});save('إضافة عضو للفريق: '+name);closeDialog();render()})}
function plans(){return head('مساحة تنمو مع شغلك.','أربع باقات — الأسعار ومدد الاشتراك أدناه من ملفك الحالي، وحدود العمليات والسجلات لم تُحدد بعد.')+`<div class="warning">هذه معاينة للباقات فقط. التفعيل والفوترة وحدود الاستخدام تحتاج الربط بالسوبر أدمن؛ تغيير الباقة هنا لا يفعّل اشتراكًا.</div><div class="plans">${[['الأساسية',299,1,2,15],['الأعمال',599,2,5,15],['المتقدمة',1299,5,12,30],['المؤسسات',2499,999,999,365]].map(([name,price,branches,staff,days],i)=>`<section class="pricing ${db.plan===i?'selected':''}"><span class="badge ${db.plan===i?'':'gray'}">${db.plan===i?'المختارة للتجربة':'الباقة '+(i+1)}</span><h2>${name}</h2><h2>${price.toLocaleString('en')} <small>ر.س</small></h2><p class="muted">لمدة ${days} يومًا</p><ul><li>✓ ${branches} فروع</li><li>✓ ${staff} موظفي جرد</li><li>✓ جرد مفتوح وبمرجع</li><li>✓ تقارير الفروقات</li></ul><button onclick="db.plan=${i};save();render();toast('تم تغيير المعاينة فقط')">معاينة الباقة</button></section>`).join('')}</div>`}
function settings(){return head('إعدادات مساحة العمل','اختبر تجربة كل دور قبل ربط الحسابات الحقيقية.')+`<section class="panel"><div class="scan"><h2>معاينة الصلاحيات</h2><p class="muted">تبديل الدور لأغراض العرض فقط، وليس تسجيل دخول أو نظام حماية.</p><label class="field">الدور المعروض<select onchange="db.role=this.value;save();go('dashboard')">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${db.role===k?'selected':''}>${v}</option>`).join('')}</select></label><h3>حالة الربط</h3><p class="muted">Google Sheets: غير متصل<br>Apps Script: بانتظار رابط النشر<br>GitHub الحالي: بانتظار رابط المستودع<br>ربط أجهزة الموظفين: غير مفعّل في المعاينة</p><button onclick="resetDemo()">إعادة ضبط البيانات التجريبية</button></div></section>`}function resetDemo(){modal('<h2>إعادة ضبط التجربة</h2><p>ستُحذف الإدخالات التي أضفتها على هذا المتصفح فقط، وتعود بيانات العرض الأصلية.</p>'+modalButtons('إعادة الضبط'),()=>{db=structuredClone(seed);save();closeDialog();go('dashboard');toast('تمت إعادة الضبط')})}
function landing(){return `<div class="marketing"><nav class="marketing-nav"><a class="wordmark" href="#" aria-label="RO الرئيسية">RO<span>✳</span></a><div><a href="#solutions">الحلول</a><a href="#method">كيف يعمل؟</a><a href="#questions">الأسئلة الشائعة</a></div><button onclick="go('dashboard')">دخول النسخة التجريبية ↖</button></nav><section class="landing-hero"><div class="hero-copy"><span class="mini-label">RO CLOUD INVENTORY / 01</span><h1>خلّ الجرد أخف.<br><mark>والصورة أوضح.</mark></h1><p>من أول باركود إلى آخر فرق.<br>مساحة واحدة ترتّب عملياتك، وتجمع فريقك،<br>وتخلي كل رقم في مكانه.</p><div class="actions"><button class="ink-button" onclick="go('dashboard')">استكشف النظام <span>↖</span></button><a class="text-cta" href="#solutions">شوف كيف نسهّلها ↙</a></div><span class="hero-footnote">واجهة عربية · جرد مفتوح أو بمرجع · تقارير واضحة</span></div><div class="orb-scene" aria-hidden="true"><div class="orb-orbit orbit-one"></div><div class="orb-orbit orbit-two"></div><div class="main-ring"></div><span class="star star-one">✳</span><span class="star star-two">✦</span><div class="floating-ticket"><span>INVENTORY, IN SYNC.</span><b>Ⅱ▏ⅢⅡ▏ⅠⅡ</b><small>كل وحدة محسوبة <i>✓</i></small></div><span class="orb-dot"></span></div><div class="hero-index">LESS FRICTION. MORE FOCUS. <span>↙</span></div></section><div class="capability-strip"><span>عدّ بوضوح.</span><i>✳</i><span>وزّع المسؤولية.</span><i>✳</i><span>راجع بثقة.</span><i>✳</i><span>قرّر على أرقام.</span></div><section class="marketing-section" id="solutions"><div class="section-heading"><h2><mark>كل خطوة، محسوبة.</mark></h2><p>من تجهيز العملية إلى مراجعة النتائج،<br>لكل مهمة مساحة واضحة.</p><span>01 / الحلول</span></div><div class="solution-grid">${[['01','ابدأ بدون تعقيد','جرد مفتوح','امسح الباركود وسجّل الكمية مباشرة، بدون الحاجة لملف أصناف مسبق.','scan','barcode-drawing'],['02','خلّ المرجع يوضّح','جرد بمرجع','ارفع قائمة أصنافك وقارن الكمية المعدودة بالمتوقعة، بما فيها الأصناف التي لم تُعدّ.','operations','compare-drawing'],['03','لكل شخص دوره','فريق مرتب','حساب الشركة يفتح العملية، يعيّن المسؤول، ويختار الموظفين المشاركين.','team','team-drawing'],['04','التكرار ما يضيع','مراجعة موثّقة','شاهد تكرار عدّ الصنف في الموقع نفسه، واعتمد الجمع أو استبعد الإدخال المكرر.','review','review-drawing']].map(([n,k,t,d,dest,art],i)=>`<article class="solution-card solution-${i}"><div><small>${n} / ${k}</small><h3><mark>${t}</mark></h3><p>${d}</p><button onclick="go('${dest}')"><span class="round-arrow">↖</span> جرّب الميزة</button></div><div class="line-art ${art}" aria-hidden="true">${i===0?'<span>Ⅱ▏ⅢⅡ▏ⅠⅡ</span><i>↗</i>':i===1?'<span>45</span><i>⇄</i><span>43</span>':i===2?'<span>○</span><span>○</span><span>○</span>':'<span>✓</span><i>✳</i>'}</div></article>`).join('')}</div></section><section class="workflow-section" id="method"><div class="workflow-intro"><span class="mini-label">02 / طريقة العمل</span><h2>عملية واضحة.<br>من البداية للنهاية.</h2><p>ثلاثة أدوار داخل الشركة.<br>كل شخص يعرف مهمته، وكل قرار له أثر.</p><button onclick="go('dashboard')">شاهد لوحة التحكم ↖</button><span class="workflow-star" aria-hidden="true">✳</span></div><div class="workflow-steps">${[['01','جهّز العملية','حساب الشركة يحدد النوع، الفرع، المسؤول وموظفي الجرد.'],['02','ابدأ العدّ','الموظف يقرأ الباركود، يدخل الكمية، ويحدد موقع الصنف.'],['03','راجع واعتمد','المسؤول يراجع التكرارات، وحساب الشركة يتابع النتائج والتقارير.']].map(([n,t,d])=>`<div><span>${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section><section class="marketing-section" id="questions"><div class="section-heading"><h2><mark>قبل أول مسحة.</mark></h2><p>إجابات تساعدك تبدأ وأنت عارف الخطوة الجاية.</p><span>03 / الأسئلة</span></div><div class="faq-list">${[['أقدر أبدأ الجرد بدون قائمة أصناف؟','نعم، اختر الجرد المفتوح لتسجيل الباركود والكميات مباشرة. وإذا عندك مرجع، ارفعه بصيغة CSV بالأعمدة barcode,name,qty.'],['كيف أعرف أن الصنف انعدّ مرتين؟','تظهر مراجعة عند تكرار الباركود في الموقع نفسه داخل العملية. يستطيع المسؤول أو حساب الشركة اعتماد الجمع أو استبعاد آخر إدخال.'],['هل النسخة الحالية متصلة ببيانات شركتي؟','هذه نسخة تجريبية تحفظ البيانات على المتصفح فقط. المزامنة السحابية وتسجيل الدخول وربط الأجهزة ستُفعّل مع استكمال ربط Apps Script وGoogle Sheets.'],['ما صيغ التقارير المتوفرة الآن؟','تدعم النسخة الحالية CSV وJSON والطباعة إلى PDF. تصدير Excel وWord والتقارير بشعار الشركة ضمن مرحلة الربط التالية.']].map(([q,a],i)=>`<details ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span>${q}<i>＋</i></summary><p>${a}</p></details>`).join('')}</div></section><section class="closing-cta"><div><span class="mini-label">READY WHEN YOU ARE.</span><h2>الخطوة الجاية؟<br><mark>جرّبها بنفسك.</mark></h2></div><button class="ink-button" onclick="go('dashboard')">افتح مساحة الجرد ↖</button><span aria-hidden="true">✳</span></section><div class="marketing-footer"><a class="wordmark" href="#">RO<span>✳</span></a><p>كل رقم، في مكانه.</p><small>نسخة تجريبية · البيانات محفوظة في متصفحك</small><button onclick="go('plans')">الباقات الأربع ↖</button></div></div>`}
function render(){document.body.dataset.page=page;let available=['dashboard','operations','scan',...(canReview()?['review','team','reports']:[]),...(canManage()?['plans']:[]),'settings'];if(!available.includes(page)&&!['detail','landing'].includes(page))page='dashboard';let icons={dashboard:'◫',operations:'▤',scan:'▥',review:'◷',team:'♧',reports:'▧',plans:'◇',settings:'⚙'};$('#nav').innerHTML=available.map(p=>`<button class="${page===p?'active':''}" onclick="go('${p}')"><span>${icons[p]}</span><em style="font-style:normal">${labels[p]}</em>${p==='review'&&groups().some(([k])=>!db.resolutions[k])?'<b>'+groups().filter(([k])=>!db.resolutions[k]).length+'</b>':''}</button>`).join('');$('#roleLabel').textContent=roles[db.role];$('#breadcrumb').textContent=labels[page]||'تفاصيل العملية';$('#app').innerHTML=({dashboard,operations,scan:scanPage,review:reviewPage,team,reports,plans,settings,landing,detail:detailPage}[page]||dashboard)();attachScan()}
render();
